sys_script_include.script:
var CLMCustomerCache = Class.create();
CLMCustomerCache.prototype = {
    initialize: function () {},
    type: 'CLMCustomerCache'
};

// Normalise so '0040074844', ' 0040074844 ' and '40074844' all match
CLMCustomerCache.norm = function (code) {
    var c = String(code === null || code === undefined ? '' : code).trim();
    if (/^\d+$/.test(c)) c = c.replace(/^0+/, '');
    return c;
};

// Built once per import run, then reused for every row
CLMCustomerCache._codes = null;

CLMCustomerCache.reset = function () {
    CLMCustomerCache._codes = null;
};

CLMCustomerCache.has = function (code) {
    if (CLMCustomerCache._codes === null) {
        var map = {};
        var count = 0;
        var gr = new GlideRecord('x_birl3_clm_clm_customer_master1');
        gr.addQuery('is_active', true);
        gr.addNotNullQuery('customer_code_sap');
        gr.query();
        while (gr.next()) {
            map[CLMCustomerCache.norm(gr.getValue('customer_code_sap'))] = true;
            count++;
        }
        CLMCustomerCache._codes = map;
        gs.info('CLMCustomerCache loaded ' + count + ' active customer codes');
    }
    return CLMCustomerCache._codes[CLMCustomerCache.norm(code)] === true;
};
